(6027985, 885970, 114225, '<td valign="top">Cute idea. I don''t like the label on the jar, a bit too basic. I wonder if it would work better either with the original label, or no label at all.</td>', 'Cute idea. I don''t like the label on the jar, a bit too basic. I wonder if it would work better either with the original label, or no label at all.', '2010-05-26 08:53:53.000000', NULL, 1),
(6027988, 884091, 114225, '<td valign="top">I like where you were going, but the lack of sharpness and the bright highlights are hurting this.</td>', 'I like where you were going, but the lack of sharpness and the bright highlights are hurting this.', '2010-05-26 08:54:34.000000', NULL, 1),
(6027991, 885899, 114225, '<td valign="top">Great capture.  One suggestion I may have is a larger DOF, so at least some of the peanutes could be in focus.</td>', 'Great capture.  One suggestion I may have is a larger DOF, so at least some of the peanutes could be in focus.', '2010-05-26 08:55:42.000000', NULL, 1),
(6027992, 885944, 65234, '<td valign="top">Punny ;-)  Pose seems a little stiff but I like the composition.  The title definitely helps here; I wonder if it would be a stronger image for this challenge if you''d done a closer view of the "planting."</td>', 'Punny ;-)  Pose seems a little stiff but I like the composition.  The title definitely helps here; I wonder if it would be a stronger image for this challenge if you''d done a closer view of the "planting."', '2010-05-26 08:56:02.000000', NULL, 1),
(6027993, 884406, 65234, '<td valign="top">Simple but well done.</td>', 'Simple but well done.', '2010-05-26 08:56:20.000000', NULL, 1),
(6027994, 885521, 114225, '<td valign="top">I like how he is coming in to the frame. Give a bit of action to the photo.</td>', 'I like how he is coming in to the frame. Give a bit of action to the photo.', '2010-05-26 08:56:22.000000', NULL, 1),
(6027996, 885784, 65234, '<td valign="top">Looks like a great squirrel feeder :-)</td>', 'Looks like a great squirrel feeder :-)', '2010-05-26 08:57:05.000000', NULL, 1),
(6027999, 884636, 114225, '<td valign="top">A very yummy world indeed. There does seem to be a lot of noise here, which is causing the photo to not be as sharp as it could be (this type of macro shot really calls for extreme sharpness).</td>', 'A very yummy world indeed. There does seem to be a lot of noise here, which is causing the photo to not be as sharp as it could be (this type of macro shot really calls for extreme sharpness).', '2010-05-26 08:57:26.000000', NULL, 1),
(6028000, 885677, 114225, '<td valign="top">Basica, but well done. Good lighting and focus.</td>', 'Basica, but well done. Good lighting and focus.', '2010-05-26 08:57:55.000000', NULL, 1),
(6028002, 885669, 65234, '<td valign="top">Oh, THAT Peanuts!  Took me a sec to make the connection.</td>', 'Oh, THAT Peanuts!  Took me a sec to make the connection.', '2010-05-26 08:58:39.000000', NULL, 1),
(6028004, 885940, 114225, '<td valign="top">I like this take on the challenge. I wonder if you could have someone gotten an angle that didn''t have power-lines running across the wording.</td>', 'I like this take on the challenge. I wonder if you could have someone gotten an angle that didn''t have power-lines running across the wording.', '2010-05-26 08:59:02.000000', NULL, 1),
(6028005, 885887, 65234, '<td valign="top">Interesting idea; think it would be better with a plain background.</td>', 'Interesting idea; think it would be better with a plain background.', '2010-05-26 08:59:25.000000', NULL, 1),
(6028006, 885514, 65234, '<td valign="top">Ick!  Thank you for not including a dead mouse.</td>', 'Ick!  Thank you for not including a dead mouse.', '2010-05-26 09:00:23.000000', NULL, 1),
(6028007, 883986, 114225, '<td valign="top">Cute! Some suggestions I would have: The white thing in the middle immediately drew my attention, it would be best to not have it. Maybe a it more sharpening so the eyes can really pop.</td>', 'Cute! Some suggestions I would have: The white thing in the middle immediately drew my attention, it would be best to not have it. Maybe a it more sharpening so the eyes can really pop.', '2010-05-26 09:00:24.000000', NULL, 1),
(6028008, 885842, 65234, '<td valign="top">Like how the peanut is actually supported by the salt.  Might prefer a less centered composition.</td>', 'Like how the peanut is actually supported by the salt.  Might prefer a less centered composition.', '2010-05-26 09:01:13.000000', NULL, 1),
(6028012, 886153, 114225, '<td valign="top">Good choice of color tone, adds to the emotion of the photo. There is something I can''t quite put my finger on that is distracting me. Maybe it''s the wide crop (compared to the subjects), but I''m not really sure.</td>', 'Good choice of color tone, adds to the emotion of the photo. There is something I can''t quite put my finger on that is distracting me. Maybe it''s the wide crop (compared to the subjects), but I''m not really sure.', '2010-05-26 09:02:23.000000', NULL, 1),
(6028015, 885737, 65234, '<td valign="top">Oh, your Grey has full feathers!  Green background sets him/her off beautifully and the image is nicely dynamic with the wings up.  Bet your model enjoyed this session :-)</td>', 'Oh, your Grey has full feathers!  Green background sets him/her off beautifully and the image is nicely dynamic with the wings up.  Bet your model enjoyed this session :-)', '2010-05-26 09:02:56.000000', NULL, 1),
(6028016, 884293, 114225, '<td valign="top">Fun idea! Feels like the color is a bit off here: the M&amp;Ms look radioactive!</td>', 'Fun idea! Feels like the color is a bit off here: the M&Ms look radioactive!', '2010-05-26 09:03:12.000000', NULL, 1),
(6028020, 885800, 114225, '<td valign="top">Fun photo. Doesn''t hold a lot of interest for me, but it is well setup and lit.</td>', 'Fun photo. Doesn''t hold a lot of interest for me, but it is well setup and lit.', '2010-05-26 09:04:02.000000', NULL, 1),
(6028023, 885354, 114225, '<td valign="top">Good idea for the challenge. I''m having a hard time finding the spot of perfect focus, which is taking away from the scene.</td>', 'Good idea for the challenge. I''m having a hard time finding the spot of perfect focus, which is taking away from the scene.', '2010-05-26 09:04:51.000000', NULL, 1),
(6028024, 886059, 65234, '<td valign="top">Interesting idea.  Think I''d like a bit more DOF or a bit more of an angle on the perspective so the crowd has more detail.</td>', 'Interesting idea.  Think I''d like a bit more DOF or a bit more of an angle on the perspective so the crowd has more detail.', '2010-05-26 09:04:53.000000', NULL, 1),
(6028027, 885486, 114225, '<td valign="top">I do love puns! I also like the use of DOF here and the way it''s lit.</td>', 'I do love puns! I also like the use of DOF here and the way it''s lit.', '2010-05-26 09:05:38.000000', NULL, 1),
(6028029, 885738, 65234, '<td valign="top">Mmmm, salty!  Like your DOF.</td>', 'Mmmm, salty!  Like your DOF.', '2010-05-26 09:05:39.000000', NULL, 1),
