(6030991, 885486, 23484, '<td valign="top">Works for me. Nice idea.</td>', 'Works for me. Nice idea.', '2010-05-28 16:51:04.000000', NULL, 1),
(6030992, 883884, 23484, '<td valign="top">Now there''s a great combo.</td>', 'Now there''s a great combo.', '2010-05-28 16:51:27.000000', NULL, 1),
(6030995, 885598, 23484, '<td valign="top">I really like the pattern. Nice job.</td>', 'I really like the pattern. Nice job.', '2010-05-28 16:52:21.000000', NULL, 1),
(6030997, 885899, 23484, '<td valign="top">Nice detail.</td>', 'Nice detail.', '2010-05-28 16:53:10.000000', NULL, 1),
(6030998, 885604, 23484, '<td valign="top">I don''t get it.</td>', 'I don''t get it.', '2010-05-28 16:53:53.000000', NULL, 1),
(6031023, 886031, 61961, '<td valign="top">I love the light and the various browns in the color palette.  Nice DOF as well.  I assume this is a simple "found" shot but it works for me better than many of the more elaborate set-ups.  This may be my challenge favorite.</td>', 'I love the light and the various browns in the color palette.  Nice DOF as well.  I assume this is a simple "found" shot but it works for me better than many of the more elaborate set-ups.  This may be my challenge favorite.', '2010-05-28 17:16:18.000000', NULL, 1),
(6031027, 885420, 61961, '<td valign="top">O.M.G.  I like it, though somehow I don''t think "Kraft" would approve!</td>', 'O.M.G.  I like it, though somehow I don''t think "Kraft" would approve!', '2010-05-28 17:19:02.000000', NULL, 1),
(6031032, 885677, 61961, '<td valign="top">Very good technicals.  I''ve never noticed before how the skin of the nut is so alive-looking.  They nuts look like alien pods.  I may never eat peanuts again.</td>', 'Very good technicals.  I''ve never noticed before how the skin of the nut is so alive-looking.  They nuts look like alien pods.  I may never eat peanuts again.', '2010-05-28 17:25:09.000000', NULL, 1),
(6031035, 885418, 61961, '<td valign="top">I had discussed with my team the idea of doing a similar shot, but I never envisioned the retro feel you''ve accomplished here.  Very cool shot.</td>', 'I had discussed with my team the idea of doing a similar shot, but I never envisioned the retro feel you''ve accomplished here.  Very cool shot.', '2010-05-28 17:26:48.000000', NULL, 1),
